'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var exp = require( '@stdlib/math/base/special/exp' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var PI = require( '@stdlib/constants/float64/pi' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );


// MAIN //

/**
* Evaluates the probability density function (PDF) for a half-normal distribution.
*
* @param {number} x - input value
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} evaluated PDF
*
* @example
* var y = pdf( 2.0, 1.0 );
* // returns ~0.108
*
* @example
* var y = pdf( 0.5, 1.0 );
* // returns ~0.352
*
* @example
* var y = pdf( -1.0, 1.0 );
* // returns 0.0
*
* @example
* var y = pdf( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = pdf( 0.0, NaN );
* // returns NaN
*
* @example
* var y = pdf( 0.0, -1.0 );
* // returns NaN
*/
function pdf( x, sigma ) {
	var C;
	if ( isnan( x ) || isnan( sigma ) || sigma <= 0.0 ) {
		return NaN;
	}
	if ( x < 0.0 ) {
		return 0.0;
	}
	C = x / sigma ;
	return ( sqrt( 2.0 / PI ) * exp( -0.5 * ( C*C ) ) / sigma );
}


// EXPORTS //

module.exports = pdf;
